package com.emp.ems;
import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.time.Instant;import java.util.*;import java.util.concurrent.ConcurrentHashMap;
@RestController @RequestMapping("/api/v1/auth")
public class AuthController{private final EmployeeRepository employees;private final PasswordEncoder encoder;private final JwtService jwt;private final String dummy;private final ConcurrentHashMap<String,Attempt> attempts=new ConcurrentHashMap<>();record Attempt(long time,int count){}record Login(@NotBlank @Email @Size(max=254)String email,@NotBlank @Size(max=72)String password){}record Session(String token,Employee.View employee,String role){}AuthController(EmployeeRepository employees,PasswordEncoder encoder,JwtService jwt){this.employees=employees;this.encoder=encoder;this.jwt=jwt;dummy=encoder.encode(UUID.randomUUID().toString());}
 @PostMapping("/login")Session login(@Valid @RequestBody Login input,HttpServletRequest request){long now=Instant.now().getEpochSecond();String key=request.getRemoteAddr()+":"+input.email().trim().toLowerCase(Locale.ROOT);if(attempts.size()>10000)attempts.entrySet().removeIf(e->e.getValue().time()<now-60);Attempt a=attempts.compute(key,(k,old)->old==null||old.time()<now-60?new Attempt(now,1):new Attempt(old.time(),old.count()+1));if(a.count()>10)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Too many sign-in attempts. Try again in a minute.");Employee e=employees.findByEmailIgnoreCase(input.email().trim()).orElse(null);boolean valid=encoder.matches(input.password(),e==null?dummy:e.passwordHash);if(e==null||!valid)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect.");attempts.remove(key);return new Session(jwt.issue(e),e.view(),e.role);}
 @PostMapping("/logout")@ResponseStatus(HttpStatus.NO_CONTENT)@Transactional void logout(@AuthenticationPrincipal CurrentUser user){employees.revokeTokens(user.id());}
 @GetMapping("/me")Employee.View me(@AuthenticationPrincipal CurrentUser user){return employees.findById(user.id()).orElseThrow().view();}
}
